NAMES = ["HALT", "LOAD", "ADD", "SUB", "STORE", "JUMP", "JUMPZ"]

def parse(text):
    """Splits a line into (label or None, the rest without the comment)."""
    text = text.split(";", 1)[0].strip()
    label = None
    if ":" in text:
        label, text = text.split(":", 1)
        label, text = label.strip(), text.strip()
    return label, text

def assemble(rest, labels, number):
    words = rest.split()
    if words[0].lstrip("-").isdigit():
        return int(words[0]), None
    name = words[0].upper()
    if name not in NAMES:
        return None, f"Line {number}: unknown instruction {words[0]}"
    if name == "HALT":
        return 0, None
    operand = words[1] if len(words) > 1 else ""
    if operand.isdigit():
        address = int(operand)
    elif operand in labels:
        address = labels[operand]
    else:
        return None, f"Line {number}: unknown label {operand}"
    return NAMES.index(name) * 100 + address, None

lines = []
while True:
    try:
        lines.append(input())
    except EOFError:
        break

# Pass one: where is every label?
labels = {}
cell = 0
error = None
for number, line in enumerate(lines, start=1):
    label, rest = parse(line)
    if label:
        if label in labels:
            error = f"Line {number}: label {label} is already defined"
            break
        labels[label] = cell
    if rest:
        cell += 1

# Pass two: turn every line into a number.
cells = []
if not error:
    for number, line in enumerate(lines, start=1):
        label, rest = parse(line)
        if not rest:
            continue
        value, error = assemble(rest, labels, number)
        if error:
            break
        cells.append(value)

if not error and len(cells) > 16:
    error = f"The program needs {len(cells)} cells, but there are only 16"

print(error if error else " ".join(str(x) for x in cells))
